/* Jaras Official: independent audio groups. Presentation-only; game logic untouched. */
(()=>{'use strict';
const KEY='jaras_audio_v52', defaultConfig={enabled:true,volume:90,countdown:true,announcer:true,applause:true,answers:true,mechanical:true,celebration:true,ui:true,voiceVolume:75};
let config={...defaultConfig};try{config={...config,...JSON.parse(localStorage.getItem(KEY)||'{}')}}catch(_){}
const embeddedAudio={"01_correct_v2.mp3":"data:audio/mpeg;base64,","02_wrong_v2.mp3":"data:audio/mpeg;base64,","03_reveal_v2.mp3":"data:audio/mpeg;base64,","04_vault_v2.mp3":"data:audio/mpeg;base64,","05_box_v2.mp3":"data:audio/mpeg;base64,","06_victory_fireworks.mp3":"data:audio/mpeg;base64,","06_victory_v2.mp3":"data:audio/mpeg;base64,","07_countdown_v2.mp3":"data:audio/mpeg;base64,"};
const sounds={start:'01_correct_v2.mp3',success:'01_correct_v2.mp3',error:'02_wrong_v2.mp3',reveal:'03_reveal_v2.mp3',steal:'03_reveal_v2.mp3',vault:'04_vault_v2.mp3',box:'05_box_v2.mp3',win:'06_victory_fireworks.mp3',tick:'07_countdown_v2.mp3',select:'03_reveal_v2.mp3',click:'03_reveal_v2.mp3'};
const group={start:'ui',success:'answers',error:'answers',reveal:'answers',steal:'answers',vault:'mechanical',box:'mechanical',win:'celebration',tick:'countdown',select:'ui',click:'ui'};
let cache=new Map(),lastTick=-1,lastTickAt=0,lastWin='';
function muted(){try{let g=JSON.parse(localStorage.getItem('jaras_global_settings')||'{}');return g.sound===false||localStorage.getItem('jaras_sound_muted')==='1'}catch(_){return false}}
function init(){return true}
function save(){try{localStorage.setItem(KEY,JSON.stringify(config))}catch(_){}document.dispatchEvent(new CustomEvent('jaras-audio-settings',{detail:{...config}}))}
function play(kind){if(!config.enabled||muted()||config[group[kind]]===false)return;
const file=sounds[kind]||sounds.click;let audio=cache.get(file);
try{if(!audio){audio=new Audio(embeddedAudio[file]);audio.preload='auto';cache.set(file,audio)}
// Independent playback prevents successive events from cutting each other off.
const a=audio.paused?audio:audio.cloneNode();a.volume=Math.min(1,Math.max(0,Number(config.volume)/100))*(kind==='tick'?.65:1);a.currentTime=0;const p=a.play();if(p&&p.catch)p.catch(()=>{});
}catch(_){} }
function classify(el){const label=((el.innerText||el.textContent||'')+' '+(el.getAttribute('aria-label')||'')).toLowerCase();
if(/خطأ|غلط|wrong|incorrect/.test(label))return 'error';
if(/صحيح|صح |نجاح|correct/.test(label))return 'success';
if(/سرق|steal/.test(label))return 'steal';
if(/فتح الخزنة|افتح الخزنة|فك الشفرة/.test(label))return 'vault';
if(/افتح الصندوق|فتح الصندوق|اختر صندوق/.test(label))return 'box';
if(/كشف|إظهار الإجابة|اظهار الاجابة|reveal/.test(label))return 'reveal';
if(/ابدأ|ابدا|لعبة جديدة|بدء|مباراة جديدة|start|play/.test(label))return 'start';
if(/اختيار|اختر|فئة|200|400|600|100|300|500/.test(label))return 'select';return 'click'}
document.addEventListener('click',e=>{let target=e.target.closest('button,a,[role="button"]');if(!target||target.disabled||target.getAttribute('aria-disabled')==='true'||target.closest('#jarasAudioControls,#jarasSoundExtras'))return;play(classify(target))},true);
function tickScan(){if(!config.enabled||!config.countdown)return;for(const el of document.querySelectorAll('#clock,#timer,#countdown,#timeLeft,[data-countdown]')){if(!el.offsetWidth||!el.offsetHeight)continue;let raw=(el.textContent||'').trim(),s=null,m=raw.match(/^(\d{1,2}):(\d{2})$/);if(m)s=Number(m[1])*60+Number(m[2]);else if(/^\d{1,2}$/.test(raw))s=Number(raw);if(s!==null&&s>=1&&s<=10&&s!==lastTick&&Date.now()-lastTickAt>550){lastTick=s;lastTickAt=Date.now();play('tick');break}}}
function winScan(){let els=[...document.querySelectorAll('#result,#results,#winner,#finalResult,#finishScreen,#gameOver')].filter(x=>x.offsetWidth&&x.offsetHeight&&!x.classList.contains('hide')&&!x.hidden);let txt=els.map(x=>x.textContent||'').join(' ').trim();if(txt&&txt!==lastWin&&/الفائز|الفريق الفائز|مبروك|تهانينا|تعادل/.test(txt)){lastWin=txt;play('win')}}
let scheduled=false;function scan(){if(scheduled)return;scheduled=true;setTimeout(()=>{scheduled=false;tickScan();winScan()},130)}
function observe(){if(document.body)new MutationObserver(scan).observe(document.body,{subtree:true,childList:true,characterData:true});scan()}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',observe);else observe();
window.JarasAudio={play,unlock:init,getSettings:()=>({...config}),setSettings:s=>{config={...config,...s};config.volume=Math.min(100,Math.max(0,Number(config.volume)||0));save();return {...config}}};
window.addEventListener('storage',e=>{if(e.key===KEY){try{config={...config,...JSON.parse(e.newValue||'{}')}}catch(_){}}});
})();
